UPDATE analysis_tabs
SET position = position + 1
WHERE project_id = '019ab04a-1000-7000-8000-000000000002' AND position >= 2
  AND NOT EXISTS (
    SELECT 1 FROM analysis_tabs f WHERE f.project_id = '019ab04a-1000-7000-8000-000000000002' AND f.kind = 'favorites'
  );
