-- VMS prospecting launch. The existing project and prospects tab keep their identities.
INSERT INTO analysis_tabs (id, project_id, name, kind, position, settings)
SELECT '01a21507-7efd-7628-a1e7-df74fe707055', p.id, 'Clientes favoritados', 'favorites', t.position + 1, t.settings
FROM projects p
JOIN analysis_tabs t ON t.id = '01a1ffdc-a669-7f7e-ac84-82b9f115df9f' AND t.project_id = p.id
WHERE p.id = '019ab04a-1000-7000-8000-000000000002'
  AND NOT EXISTS (SELECT 1 FROM analysis_tabs f WHERE f.project_id = p.id AND f.kind = 'favorites');
