INSERT INTO research_prospects (
  id, project_id, reference_key, city_code, state_code, name, segment, priority, enrichment_level, profile
)
SELECT seed.id, p.id, profile->>'id', profile->>'cityCode', profile->>'state',
  profile->>'name', profile->>'segment', profile->>'priority', 'researched', profile
FROM seed CROSS JOIN projects p
WHERE p.id = '019ab04a-1000-7000-8000-000000000002'
ON CONFLICT (project_id, reference_key) DO NOTHING;
